from pages import *
from fig import *
i=13
SAR=lambda: devi(sari='#ffffff',skin='#fbeee0',items=('book','rosary','lotus'),seat=True,halo='#dfe9f6')
def swan(): return '<path d="M-30 0 q0 -20 30 -20 h20 q10 -30 0 -40 q-8 -6 -14 0" fill="#fff" stroke="#111" stroke-width="2"/><path d="M-30 0 q30 10 60 0 q0 -20 -10 -20" fill="#fff"/><path d="M-14 -38 l-8 2" stroke="#e0a800" stroke-width="3"/>'
COV=covart('Sarasvatī in white seated with a vīṇā, book and rosary, a swan beside her, and a stack of books and a pen placed before her for worship; a young girl worshipped with flowers on the right',
 g(160,196,1.2,devi(sari='#ffffff',skin='#fbeee0',items=('book','rosary'),seat=True,halo='#dfe9f6'))+g(170,170,.8,vina())+g(60,196,.9,swan())+g(270,196,1,books_stack())+g(380,196,1,person('#c0392b'))+g(340,180,.6,lotus()))
pages=[foreword(i,['The nine nights are nearly over. On the last days two great observances meet: <b>Sarasvatī Pūjā</b>, when books, pens and instruments are placed before the Goddess of learning, and <b>Durgāṣṭamī</b>, the holy eighth day, with <b>Kanyā Pūjā</b>, the worship of young girls, and the intense <b>Sandhi Pūjā</b>.','In Karnataka homes Sarasvatī arrives on the day of the <b>Mūla</b> star; in Bengal the eighth day is the height of Durgā Pūjā. This part explains both.'],
 [('z','No homework while the books are with Sarasvatī?'),('b','That is the children’s favourite rule. Books rest with the Goddess, and on Vijayadaśamī you take them back blessed.')]),
 glance([('Sarasvatī Pūjā','Books, pens, instruments and tools of learning worshipped; in the south usually from the Mūla star day until Vijayadaśamī'),('Who','Sarasvatī: Goddess of learning, speech, music and the arts'),('Durgāṣṭamī','The eighth day: Mahāgaurī’s day, among the holiest of Navarātri'),('Kanyā Pūjā','Young girls worshipped as the Goddess, fed and given gifts (Aṣṭamī or Navamī)'),('Sandhi Pūjā','At the junction of Aṣṭamī and Navamī: Cāmuṇḍā’s victory over Caṇḍa and Muṇḍa'),('Texts','Devī Māhātmya chapter 7 for Sandhi Pūjā; Sarasvatī hymns')],svg(560,160,'Books placed before Sarasvatī on the left, and young girls seated for worship on the right',g(150,150,1,SAR())+g(260,150,.9,books_stack())+''.join(g(390+k*40,150,.8,person(c,seat=True)) for k,c in enumerate(['#c0392b','#e0a800','#2a9d6f'])))),
 reading('mula','SARASVATĪ ARRIVES ON MŪLA','When the books go to the Goddess',svg(560,180,'A night sky with the Mūla star group highlighted, and below it a family placing books on a decorated stand',''.join(f'<circle cx="{x}" cy="{y}" r="{r}" fill="#fff8d0"/>' for x,y,r in [(80,40,3),(110,55,3),(140,50,3),(160,70,3),(190,60,4)])+'<rect width="560" height="100" fill="#1f1a2e" opacity=".15"/>'+g(140,100,1,'')+lab(140,90,'Mūla nakṣatra')+ground(560,180,160,'#e9d6c0')+g(380,160,1,'<rect x="-50" y="-30" width="100" height="30" fill="#e8c06a" stroke="#111" stroke-width="2"/>')+g(380,130,1,books_stack())+g(470,160,.9,person('#c0392b'))),[
  '<b>Āvāhana on Mūla.</b> In South India, Sarasvatī is invited (<i>āvāhana</i>) on the day the moon is in the <b>Mūla</b> nakṣatra during Navarātri, usually around the seventh day. That is when the books go to her.','<b>What is placed.</b> Children’s schoolbooks, holy books, account ledgers, pens, musical instruments, paintbrushes: anything with which one learns or makes art is arranged before her image and decorated with turmeric, kuṅkuma and flowers.','<b>The days that follow.</b> Worship continues daily (on the following nakṣatras, by many almanacs, with the main worship on the day after Mūla), and the books stay with her until Vijayadaśamī, when they are taken back and used, often with a first act of writing or reading.','<b>Elsewhere.</b> Many regions keep Sarasvatī Pūjā on Navamī alone; Bengal’s great Sarasvatī Pūjā is a separate festival in spring (Vasanta Pañcamī). Traditions differ.'],
  [('z','Why does the timing go by a star?'),('b','Mūla means “root”. Starting the worship of learning at the root: the almanac and the meaning agree nicely.')],'On the Mūla star, <b>books and instruments go to Sarasvatī</b>.'),
 cards('who','WHO IS SARASVATĪ','Her form and symbols',svg(560,200,'Sarasvatī in white seated on a lotus, playing a vīṇā, with book and rosary in her other hands and a swan at her feet, with labels',g(280,190,1.4,SAR())+g(290,150,1,vina())+g(150,190,1,swan())+lab(450,60,'book: knowledge')+lab(450,110,'rosary: meditation')+lab(450,160,'vīṇā: music')+lab(120,140,'swan')),[
  ('📖','Book','The Veda and all learning; also the written word, which she guards.'),('🎶','Vīṇā','Music and the arts. She is the patron of every musician and dancer.'),('📿','Rosary','Meditation and the repetition of mantras: learning turned inward.'),('🦢','Swan','The <i>haṃsa</i> is said to separate milk from water: the power to tell the true from the false.')],
  [('z','Is she Brahmā’s wife?'),('b','In the Purāṇas, yes, and in the Devī Māhātmya the Goddess of the third story is Mahāsarasvatī. On these last nights she is the learning side of the one Devī.')],'Book, vīṇā, rosary, swan: <b>knowledge, art, meditation, discernment</b>.'),
 story('placing','PLACING THE BOOKS','A simple Sarasvatī Pūjā at home',strip('Three panels: a child arranging books on a stand; drawing a symbol on a slate; the family doing ārati before the books',[(g(72,150,.7,person('#1d6fb8'))+g(110,120,.6,books_stack()),'#fff3cf'),(g(72,110,1.2,'<rect x="-40" y="-26" width="80" height="52" fill="#2a3a2a" stroke="#111" stroke-width="2"/><path d="M-20 0 q10 -16 20 0 q10 16 20 0" fill="none" stroke="#fff" stroke-width="3"/>'),'#eef2fb'),(g(72,130,1,'<path d="M-24 0 h48 l-6 8 h-36z" fill="#c9a24a"/>'+''.join(f'<g transform="translate({x} 0)">'+lamp('#e0a800')+'</g>' for x in (-14,0,14))),'#fde4e4')],['books on the stand','a first letter','ārati']),
  'Each family has its own way, but a simple Sarasvatī Pūjā often goes like this:',[
  '<b>Clean and arrange.</b> Gather books, pens and instruments, clean them, and arrange them before Sarasvatī’s image, often on a raised stand.','<b>Mark them.</b> Dab each with turmeric and kuṅkuma, and lay a flower on it.','<b>Invite her.</b> Light a lamp, say a prayer or verse to Sarasvatī, and ask her to bless all learning in the house.','<b>Offer.</b> Fruit, sweets and flowers; children may write a sacred syllable or their name on a slate or in rice.','<b>Leave them.</b> The books rest with her until Vijayadaśamī, when they are taken back with a prayer and a first piece of study.'],
  [('z','What if I have an exam the next day?'),('b','Families are practical; many keep a token book on the stand and study from the rest. Sarasvatī is the last goddess to object to studying.')],'Books cleaned, marked, offered, <b>and returned blessed</b>.'),
 reading('ashtami','DURGĀṢṬAMĪ','The great eighth day',svg(560,180,'The goddess Mahāgaurī in white with lamps and a large drum (dhāk) and conch, the sounds of the eighth day',g(200,170,1.1,devi(sari='#ffffff',skin='#fbeee0',items=('trident','damaru','abhaya','lotus'),halo='#fff8d0'))+g(360,150,1.2,'<ellipse rx="24" ry="30" fill="#c9783a"/><path d="M-24 0 h48" stroke-width="2"/>')+g(460,150,1.2,conch())+lab(360,176,'the dhāk drum')+lab(460,176,'conch')),[
  '<b>Mahāṣṭamī.</b> The eighth day of the bright fortnight, <b>Durgāṣṭamī</b> or Mahāṣṭamī, is among the holiest days of the year for devotees of the Goddess. In the nine-Durgā order it belongs to '+link(10,'Mahāgaurī')+'.','<b>In Bengal.</b> Mahāṣṭamī is the high point of Durgā Pūjā: <i>puṣpāñjali</i>, the offering of flowers with chanted verses, draws whole neighbourhoods to the pandal in the morning.','<b>Fasts.</b> Many who do not fast for nine days fast on Aṣṭamī alone, ending after the evening worship.','<b>Weapons and strength.</b> In some regions the Goddess’s weapons are worshipped on this day too (<i>astra pūjā</i>), a cousin of the Āyudha Pūjā of the next day.'],
  [('z','Why is the eighth day so special?'),('b','Because of what happens at its end: the Sandhi hour, when Cāmuṇḍā wins her great battle. Everything builds toward it.')],'Durgāṣṭamī: <b>flowers, fasting and the build-up to the Sandhi hour</b>.'),
 reading('kanya','KANYĀ PŪJĀ','Worshipping the Goddess in young girls',svg(560,180,'Nine young girls seated in a row on a mat, a family washing their feet and serving food on leaf plates',ground(560,180,160,'#e9d6c0')+''.join(g(50+k*55,160,.75,person(['#c0392b','#e0a800','#2a9d6f','#7a3fa0','#ff8c1a','#1d6fb8','#c0392b','#e0a800','#2a9d6f'][k],seat=True)) for k in range(9))+''.join(f'<ellipse cx="{50+k*55}" cy="170" rx="18" ry="5" fill="#5a8a3a" stroke="#111"/>' for k in range(9))),[
  '<b>The custom.</b> On Aṣṭamī or Navamī many families invite young girls, often nine, sometimes with a small boy as Bhairava or Gaṇeśa, and worship them as forms of the Devī. In Bengal this is <b>Kumārī Pūjā</b>, done on Mahāṣṭamī with one girl worshipped in great ceremony.','<b>How it is done.</b> The girls’ feet are washed, a tilaka applied, red threads tied, and they are seated on a mat and fed a festive meal, often halwa, pūrī and chickpeas in the north. They receive gifts: bangles, clothes, money.','<b>Why.</b> The Devī is worshipped in every woman; in a young girl, before the world has touched her, devotees say she is especially present. The nine Durgās become nine living girls.','<b>A lesson.</b> Many read the ritual as a yearly reminder of respect: a household that bows to its daughters for a day is asked to honour them all year.'],
  [('z','What if there aren’t nine girls nearby?'),('b','Families invite whoever they can, even one. The ritual is about seeing the Goddess, not counting.')],'Kanyā Pūjā: <b>the Goddess seen in young girls</b>.'),
 story('sandhi','SANDHI PŪJĀ','The junction hour and Cāmuṇḍā (Devī Māhātmya 7)',strip('Three panels: the demons Caṇḍa and Muṇḍa attacking; a fearsome dark goddess leaping from the Devī’s brow; the goddess holding the two severed heads up to the Devī',[(g(45,155,.65,demon())+g(100,155,.65,demon('#6a2a3a')),'#fde4e4'),(g(72,165,.7,devi(skin='#3a3a52',sari='#3a3a40',items=('sword','hook'),hair_open=True,fierce=True,halo='#5a3a6a')),'#1f1a2e'),(g(72,165,.7,devi(sari='#c0392b',items=('trident','sword')))+'<circle cx="30" cy="60" r="8" fill="#6a2a3a" stroke="#111"/><circle cx="114" cy="60" r="8" fill="#2a6a3a" stroke="#111"/>','#fff3cf')],['Caṇḍa and Muṇḍa attack','Kālī springs from her brow','“Cāmuṇḍā” is her name']),
  'At the exact junction (<i>sandhi</i>) of Aṣṭamī and Navamī, the last 24 minutes of the eighth day and the first 24 of the ninth, comes the most intense worship of the festival.',[
  'The Devī Māhātmya tells how Śumbha sent the demons <b>Caṇḍa</b> and <b>Muṇḍa</b> to capture the Devī.','Her face darkened with anger, and from her brow sprang <b>Kālī</b>, terrible, gaunt, with a garland of heads.','Kālī tore through the demon army and cut off Caṇḍa’s and Muṇḍa’s heads, bringing them to the Devī.','The Devī named her <b>Cāmuṇḍā</b>, from Caṇḍa and Muṇḍa. Tradition says the battle ended at this junction hour; our <a href="/devi/devi-mahatmya/part-12/">Devī Māhātmya Part 12</a> gives the verses.','So in the Sandhi Pūjā Cāmuṇḍā is worshipped. In Bengal 108 lamps are lit and 108 lotuses offered, while the drums play at full force.'],
  [('z','Cāmuṇḍā! Like Cāmuṇḍī Hill?'),('b','The same name. Mysuru’s Cāmuṇḍeśvarī carries this victory and Mahiṣa’s together.')],'At the junction hour, <b>Cāmuṇḍā’s victory</b>: 108 lamps, 108 lotuses.'),
 reading('meaning','THE LAST DAYS’ MEANING','Learning, purity and victory',svg(560,160,'Three symbols in a row: a book, a white flower and a lamp blazing at the junction of two days',g(130,120,1.4,book())+g(280,110,1.4,lotus('#ffffff','#f4f1ea'))+g(430,130,1.6,lamp())+lab(130,150,'learning')+lab(280,150,'purity')+lab(430,150,'the junction')),[
  '<b>Sarasvatī last.</b> In the three-by-three count of '+link(0,'Part 1')+', the last nights belong to Sarasvatī: after clearing and growing comes knowledge. Placing the books with her says that learning, too, is a gift of the Goddess.','<b>Aṣṭamī’s purity.</b> Mahāgaurī’s whiteness and the worship of young girls make Aṣṭamī a day of purity.','<b>The junction.</b> Many teachers read the Sandhi hour as the moment between two states, where the decisive inner victory is won. Junctions (dawn, dusk, the meeting of days) are always sacred in Indian worship.','<b>Toward the tenth.</b> After this the festival turns outward again: tools, weapons, the śamī tree and victory ('+link(14,'Part 15')+').'],
  [('z','So the festival ends with books and battles?'),('b','With wisdom and with victory. That is the right order: first know, then win.')],'Learning, purity and the junction hour: <b>the festival’s inner climax</b>.'),
 end(i,['<b>Sarasvatī Pūjā.</b> From the Mūla star, books and instruments rest with the Goddess.','<b>Her symbols.</b> Book, vīṇā, rosary and swan.','<b>Durgāṣṭamī.</b> The great eighth day: flowers, fasts, Mahāgaurī.','<b>Kanyā Pūjā.</b> Young girls worshipped as the Goddess.','<b>Sandhi Pūjā.</b> At the junction hour, Cāmuṇḍā’s victory over Caṇḍa and Muṇḍa.'],'Part 15 is the finale at home: Mahānavamī and Āyudha Pūjā, then Vijayadaśamī with the śamī tree, Rāma’s victory and new beginnings.','Sarasvatī Pūjā and Durgāṣṭamī'),
 sources([('Text:','Devī Māhātmya chapter 7 (Caṇḍa, Muṇḍa, Cāmuṇḍā), our <a href="/devi/devi-mahatmya/part-12/">Part 12</a>.'),('Customs:','Wikipedia, “Navaratri”, “Saraswati Puja”, “Kanya Puja”, “Durga Puja” (Sandhi Pūjā, 108 lamps and lotuses, Kumārī Pūjā). Karnataka Tourism, “Gombe Habba” (Sarasvatī Pūjā late in the nine days).')],'the exact days of Sarasvatī worship (almanacs and regions differ); the length of the Sandhi period as 48 minutes (common but varies); foods for Kanyā Pūjā.','Customs given in their common forms; your almanac sets the days.')]
build(i,'PART 14 OF 16 · BOOKS · GIRLS · THE JUNCTION HOUR',COV,'Sarasvatī, the books and the young Goddesses',
 'When and why <b>books go to Sarasvatī</b>, who she is, a simple pūjā, then <b>Durgāṣṭamī</b>, <b>Kanyā Pūjā</b> and the <b>Sandhi hour</b> of Cāmuṇḍā.',
 'Sarasvatī Pūjā and Durgāṣṭamī in Navarātri: Sarasvatī invited on the Mūla star, her symbols, placing books and instruments, the great eighth day, Kanyā Pūjā (Kumārī Pūjā), and the Sandhi Pūjā of Cāmuṇḍā from Devī Māhātmya 7. Part 14 of the illustrated Navarātri series.',pages)
